{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const unresolved = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const culprits = [...new Set(unresolved.map(i => i.culprit))];
  const out: Record<string, unknown> = {};
  for (const c of culprits) {
    const { issues: found } = await sdk.linear.searchIssues({ query: c });
    out[c] = found.map(f => ({ identifier: f.identifier, title: f.title, description: f.description, state: f.state }));
  }
  return { unresolvedIds: unresolved.map(i => i.shortId), culprits, out };
}"}

