{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const unresolved = issues.filter(i => i.status === "unresolved" && i.count >= 0);

  // Group Sentry issues by culprit: at most one Linear issue per culprit.
  const byCulprit = new Map<string, string[]>();
  for (const i of unresolved) {
    const list = byCulprit.get(i.culprit) ?? [];
    list.push(i.shortId);
    byCulprit.set(i.culprit, list);
  }

  // Full Linear issue list (empty query returns everything) for exact mention checks.
  const { issues: allLinear } = await sdk.linear.searchIssues({ query: "" });

  const alreadyMentioned: string[] = [];
  const toCreate: { culprit: string; sentryIssues: string[] }[] = [];
  for (const [culprit, sentryIds] of byCulprit) {
    const mentioned = allLinear.some(
      l => l.title.includes(culprit) || l.description.includes(culprit),
    );
    if (mentioned) alreadyMentioned.push(culprit);
    else toCreate.push({ culprit, sentryIssues: sentryIds });
  }

  const created: { culprit: string; sentryIssues: string[]; issue: unknown }[] = [];
  for (const c of toCreate) {
    const issue = await sdk.linear.createIssue({
      title: `[Sentry] ${c.culprit}`,
      description: c.culprit,
    });
    created.push({ ...c, issue });
  }

  return {
    sentryUnresolved: unresolved.map(i => i.shortId),
    culpritCount: byCulprit.size,
    alreadyMentioned,
    createdCount: created.length,
    created,
  };
}"}

